import { utf8fromString } from '@exodus/bytes/utf8.js'

// Uint8Array (or any subclass like Buffer) or a valid Unicode string
export function fromUint8orString(arg, name) {
  if (arg instanceof Uint8Array) return arg
  if (typeof arg === 'string') return utf8fromString(arg)
  throw new Error(`Expected${name ? ` ${name} to be` : ''} an Uint8Array or a string`)
}

/*
  Methods below are for /hash and /hmac, which support array input to avoid concatenation

  Input is one of:
   * Uint8Array (or any subclass like Buffer)
   * A valid Unicode string
   * A non-empty array of Uint8Array instances

  Node.js and Noble hashes support chunked input, browsers don't
*/

/**
  Platforms that support chunked input can use this

  @returns {Uint8Array | Uint8Array[]}
*/
export function parseHashInput(arg) {
  // This also covers Buffer as they are Uint8Array instances
  if (arg instanceof Uint8Array) return arg
  if (typeof arg === 'string') return utf8fromString(arg)
  if (Array.isArray(arg)) {
    // Allow hashing an non-empty array of Uint8Array instances or Buffer instances
    if (!(arg.length > 0)) throw new TypeError('An array in hash argument must not be empty')
    for (const x of arg) {
      if (!(x instanceof Uint8Array)) throw new TypeError('Unsupported entry in hash argument')
    }
    return arg
  }
  throw new TypeError('Unsupported hash argument')
}

/**
  Squash the input into a single Uint8Array

  Platforms that don't support chunked input (i.e. browsers) should use this

  @returns {Uint8Array}
*/
export function combineHashInput(arg) {
  const parsed = parseHashInput(arg)
  if (parsed instanceof Uint8Array) return parsed
  if (Array.isArray(parsed)) return Buffer.concat(parsed) // TODO: use @exodus/bytes
  throw new Error('Unreachable')
}

/**
  Compression input is one of:
   * A Uint8Array instance
   * A non-empty array of Uint8Array instances
   * (In compression only) A valid Unicode string

  @returns Uint8Array[]
*/
export function fromCompressInput(arg, canBeString = false) {
  if (Array.isArray(arg)) {
    if (!(arg.length > 0)) throw new TypeError('An array in compress argument must not be empty')
    for (const x of arg) {
      if (!(x instanceof Uint8Array)) throw new TypeError('Unsupported entry in compress argument')
    }
    return arg
  }

  if (arg instanceof Uint8Array) return [arg]
  if (canBeString) {
    if (typeof arg === 'string') return [fromUint8orString(arg)]
    throw new Error('Expected a Uint8Array, Uint8Array[], or a string')
  }
  throw new Error('Expected a Uint8Array or Uint8Array[]')
}
